export type BrowserType = "chromium" | "firefox" | "webkit";

export interface BrowserLaunchOptions {
  readonly headless?: boolean;
  readonly slowMo?: number;
  readonly viewport?: { readonly width: number; readonly height: number };
  readonly recordTrace?: boolean;
  readonly traceOutputDir?: string;
}

export interface RouteInterceptRule {
  readonly urlPattern: string | RegExp;
  readonly status: number;
  readonly contentType?: string;
  readonly responseBody: string | Record<string, unknown>;
  readonly delayMs?: number;
}

export interface ElementStateCondition {
  readonly state: "attached" | "detached" | "visible" | "hidden" | "stable";
  readonly timeoutMs?: number;
}

export interface TraceActionEvent {
  readonly actionId: string;
  readonly type: "navigate" | "click" | "fill" | "hover" | "press" | "wait";
  readonly selector?: string;
  readonly startTimeMs: number;
  readonly durationMs: number;
  readonly error?: string;
  readonly domSnapshotBefore?: string;
  readonly domSnapshotAfter?: string;
}

export interface TraceNetworkRequest {
  readonly requestId: string;
  readonly url: string;
  readonly method: "GET" | "POST" | "PUT" | "DELETE" | "PATCH";
  readonly status: number;
  readonly durationMs: number;
  readonly failureReason?: string;
}

export interface PlaywrightTraceArchive {
  readonly traceId: string;
  readonly browser: BrowserType;
  readonly totalDurationMs: number;
  readonly actions: readonly TraceActionEvent[];
  readonly networkRequests: readonly TraceNetworkRequest[];
  readonly consoleMessages: readonly { readonly level: "info" | "warn" | "error"; readonly text: string }[];
}

export interface FlakinessDiagnosticReport {
  readonly traceId: string;
  readonly passed: boolean;
  readonly flakinessIdentified: boolean;
  readonly rootCauseCategory?: "hydration_race" | "network_timeout" | "unhandled_exception" | "strict_mode_violation";
  readonly failingAction?: TraceActionEvent;
  readonly problematicRequests: readonly TraceNetworkRequest[];
  readonly recommendations: readonly string[];
}

export interface TestResult {
  readonly testName: string;
  readonly durationMs: number;
  readonly status: "passed" | "failed" | "skipped" | "flaky";
  readonly retries: number;
  readonly errorMessage?: string;
  readonly screenshotPath?: string;
  readonly tracePath?: string;
}

